mapper.update:
UPDATE `expert_profile` p
LEFT JOIN (
    SELECT expert_id, COUNT(1) AS review_count, ROUND(AVG(rating), 2) AS avg_rating
    FROM `expert_review`
    WHERE expert_id = #{expertId}
    GROUP BY expert_id
) r ON r.expert_id = p.id
SET p.review_count = COALESCE(r.review_count, 0),
    p.rating = COALESCE(r.avg_rating, 5.00)
WHERE p.id = #{expertId}

